export const gmaps = (query) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
export const gphotos = (query) => `https://www.google.com/maps/search/${encodeURIComponent(`${query} photos`)}`;
export const placeMapLink = (place) => {
  if (!place || typeof place !== 'object') return requestedMapLink;
  if (placeMapOverrides[place.id]) return placeMapOverrides[place.id];
  return gmaps(`${place.name || 'Oaxaca'} ${place.area || ''} Oaxaca Mexico`);
};

