export const stop = (id, category, name, area, rating, duration, emoji, accent, price, neighborhood, bestFor, localTip, safetyTip, lat, lng, query = null, mapsOverride = null, description = null) => {
  const mapUrl = mapsOverride || placeMapOverrides[id] || gmaps(`${name} ${area} Oaxaca Mexico`);
  return {
    id, category, name, area, rating, duration, emoji, accent, price, neighborhood, bestFor, localTip, safetyTip, lat, lng,
    maps: mapUrl,
    photos: gphotos(`${query || name} Oaxaca`),
    description: description || bestFor,
    image: placeImages[id] || ''
  };
};


