export const places = allPlaces.filter(place => place?.id !== 'ocotlan-market' && place?.name !== 'Mercado de Ocotlán de Morelos');

const pueblosMancomunadosIndex = allPlaces.findIndex((place) => place.id === 'pueblos-mancomunados-sierra-norte' || place.id === 'pueblos-mancomunados' || place.name === 'Pueblos Mancomunados Sierra Norte');
if (pueblosMancomunadosIndex !== -1) {
  allPlaces.splice(pueblosMancomunadosIndex, 1);
}

